using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "GainByDieTierRewardEventAction", menuName = "Data/BattleSceneSetups/Events/EventActions/GainByDieTierRewardEventAction", order = 0)]
public class GainByDieTierRewardEventAction : RewardEventAction
{
	[SerializeField]
	protected DiceTier diceTier;

	[SerializeField]
	protected int diceAmount;

	[SerializeField]
	protected int resourceAmount = 1;

	[SerializeField]
	protected Reward reward;

	public override void ExecuteAction(EventButton eventButton)
	{
		ClearingReward clearingReward = base.clearingReward;
		base.clearingReward = Object.Instantiate(base.clearingReward);
		base.clearingReward.SetRewards(GetRewards());
		base.ExecuteAction(eventButton);
		base.clearingReward = clearingReward;
	}

	protected virtual Reward[] GetRewards()
	{
		return new Reward[0];
	}

	public int GetMultiplier()
	{
		return Mathf.FloorToInt((float)ReferenceSingleton<AssetsReference>.Instance.DicePool.GetDiceAmountFromSpecificTier(diceTier) / (float)diceAmount);
	}

	public override bool IsEventButtonEnabled()
	{
		return GetMultiplier() >= 1;
	}
}
